import sys
import os
import xml.etree.ElementTree as ET
from Crypto.Cipher import AES
from Crypto.Util.Padding import pad, unpad
import base64

def transform_bytes(data, passphrase):
    key = passphrase.encode('utf-8')
    iv = os.urandom(16)
    cipher = AES.new(key, AES.MODE_CBC, iv)
    return base64.b64encode(iv + cipher.encrypt(pad(data, AES.block_size)))

def inverse_transform_bytes(encrypted_data):
    encrypted_data = base64.b64decode(encrypted_data)
    iv = encrypted_data[:16]
    ciphertext = encrypted_data[16:]
    key = sys.argv[2].encode('utf-8')
    cipher = AES.new(key, AES.MODE_CBC, iv)
    return unpad(cipher.decrypt(ciphertext), AES.block_size)

def main():
    if len(sys.argv) != 3:
        print("Usage: python filecrypt.py <mode> <passphrase>", file=sys.stderr)
        sys.exit(1)

    mode = sys.argv[1]
    passphrase = sys.argv[2]

    try:
        tree = ET.parse('config.xml')
        root = tree.getroot()
    except (IOError, ET.ParseError):
        print("config error", file=sys.stderr)
        sys.exit(1)

    for file_elem in root.findall('file'):
        path = file_elem.get('path')
        if not path:
            continue

        if mode == 'encrypt':
            try:
                with open(path, 'rb') as f:
                    data = f.read()
                encrypted = transform_bytes(data, passphrase)
                with open(path + '.enc', 'wb') as f:
                    f.write(encrypted)
            except IOError as e:
                print(f"missing file: {path}", file=sys.stderr)
        elif mode == 'decrypt':
            try:
                with open(path + '.enc', 'rb') as f:
                    data = f.read()
                decrypted = inverse_transform_bytes(data)
                with open(path, 'wb') as f:
                    f.write(decrypted)
            except IOError as e:
                print(f"missing file: {path}.enc", file=sys.stderr)
        else:
            print(f"Invalid mode: {mode}", file=sys.stderr)
            sys.exit(1)

if __name__ == "__main__":
    main()
